// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type LowBatteryAnimationProps = Record<string, any>;

const LowBatteryAnimation: React.FC<LowBatteryAnimationProps> = ({
  backgroundColor = "#0f0f11",
  transparentBackground = false,
  durationInSeconds = 5,
  startPercentage = 100,
  endPercentage = 5,
  outlineColor = "#ffffff",
  normalFillColor = "#4ade80",
  lowFillColor = "#facc15",
  criticalFillColor = "#ef4444",
  textColor = "#ffffff",
  showText = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive sizing based on canvas smallest dimension
  const s = Math.min(width, height);
  const batteryWidth = s * 0.45;
  const batteryHeight = s * 0.85;
  const terminalWidth = batteryWidth * 0.35;
  const terminalHeight = s * 0.04;
  const borderWidth = s * 0.015;
  const padding = s * 0.015;
  const outerRadius = s * 0.05;
  const innerRadius = s * 0.035;

  // Timings
  const introDuration = fps; // 1 second intro
  const outroDuration = fps; // 1 second hold at the end
  const totalFrames = fps * durationInSeconds;
  
  const drainStartFrame = introDuration;
  const drainEndFrame = totalFrames - outroDuration;

  // Intro Spring Animation
  const entranceScale = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 100 },
  });

  // Calculate current battery level
  const currentPercentage = interpolate(
    frame,
    [drainStartFrame, drainEndFrame],
    [startPercentage, endPercentage],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Determine fill color based on level
  const getFillColor = (pct: number) => {
    if (pct <= 15) return criticalFillColor;
    if (pct <= 30) return lowFillColor;
    return normalFillColor;
  };

  const currentColor = getFillColor(currentPercentage);
  const isCritical = currentPercentage <= 15;

  // Pulsing effect for critical state
  const pulseFactor = interpolate(
    Math.sin(frame * 0.25),
    [-1, 1],
    [0.4, 1]
  );
  
  const fillOpacity = isCritical ? pulseFactor : 1;
  const glowOpacity = isCritical ? interpolate(pulseFactor, [0.4, 1], [0.1, 0.6]) : 0;
  const glowBlur = s * 0.1;

  // Text animation
  const textOpacity = interpolate(frame, [15, 45], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const textY = interpolate(frame, [15, 45], [20, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        flexDirection: "column",
        fontFamily: robotoMonoFamily,
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          transform: `scale(${entranceScale})`,
          transition: "none",
        }}
      >
        {/* Battery Terminal (Top Nub) */}
        <div
          style={{
            width: terminalWidth,
            height: terminalHeight,
            backgroundColor: outlineColor,
            borderTopLeftRadius: innerRadius,
            borderTopRightRadius: innerRadius,
            marginBottom: -2, // Prevent visual gap
            zIndex: 2,
          }}
        />

        {/* Battery Main Body */}
        <div
          style={{
            width: batteryWidth,
            height: batteryHeight,
            border: `${borderWidth}px solid ${outlineColor}`,
            borderRadius: outerRadius,
            padding: padding,
            display: "flex",
            flexDirection: "column-reverse", // Fill grows from bottom up
            position: "relative",
            zIndex: 3,
            backgroundColor: isCritical ? `${criticalFillColor}${Math.round(glowOpacity * 20)}` : "transparent",
            boxShadow: isCritical ? `0 0 ${glowBlur}px ${criticalFillColor}${Math.round(glowOpacity * 255).toString(16).padStart(2, '0')}` : "none",
          }}
        >
          {/* Battery Fill */}
          <div
            style={{
              width: "100%",
              height: `${currentPercentage}%`,
              backgroundColor: currentColor,
              borderRadius: innerRadius,
              opacity: fillOpacity,
              transition: "none", // Prevent CSS transitions, strictly frame-based
            }}
          />
        </div>
      </div>

      {/* Percentage Text */}
      {showText && (
        <div
          style={{
            marginTop: s * 0.08,
            fontSize: s * 0.08,
            fontWeight: 700,
            color: isCritical ? criticalFillColor : textColor,
            opacity: textOpacity * (isCritical ? fillOpacity : 1),
            transform: `translateY(${textY}px) scale(${entranceScale})`,
            textShadow: isCritical ? `0 0 ${glowBlur * 0.5}px ${criticalFillColor}` : "none",
            transition: "none",
          }}
        >
          {Math.round(currentPercentage)}%
        </div>
      )}
    </AbsoluteFill>
  );
};

export default LowBatteryAnimation;